import java.sql.*;

public class PrimeraConexion {

    public static void main(String[] args) {
        // Datos de conexion
        String url = "jdbc:postgresql://localhost:5432/mibase";
        String user = "postgres";
        String password = "password";

        Connection conn = null;

        try {
            // 1. Establecer conexion
            conn = DriverManager.getConnection(url, user, password);
            System.out.println("Conexion exitosa a PostgreSQL!");
            System.out.println("URL: " + conn.getMetaData().getURL());
            System.out.println("Driver: " + conn.getMetaData().getDriverName());
            System.out.println("Version: " + conn.getMetaData().getDriverVersion());

        } catch (SQLException e) {
            System.out.println("Error de conexion: " + e.getMessage());
            System.out.println("SQL State: " + e.getSQLState());
            System.out.println("Error Code: " + e.getErrorCode());
        } finally {
            // 2. Cerrar conexion
            if (conn != null) {
                try {
                    conn.close();
                    System.out.println("Conexion cerrada.");
                } catch (SQLException e) {
                    e.printStackTrace();
                }
            }
        }
    }
}

// Puntos clave:
// 1. url: formato jdbc:postgresql://host:puerto/baseDatos
// 2. DriverManager.getConnection() puede lanzar SQLException
// 3. Siempre cerrar la conexion en finally (o usar try-with-resources)
// 4. getMetaData() devuelve informacion sobre la BD y el driver

import java.sql.*;

public class ConexionSegura {

    private static final String URL = "jdbc:postgresql://localhost:5432/mibase";
    private static final String USER = "postgres";
    private static final String PASS = "password";

    public static void main(String[] args) {

        // try-with-resources: cierra automaticamente los recursos
        try (Connection conn = DriverManager.getConnection(URL, USER, PASS)) {

            System.out.println("Conectado a: " + conn.getMetaData().getURL());
            System.out.println("Auto-commit: " + conn.getAutoCommit());

            // La conexion se cierra automaticamente al salir del bloque try

        } catch (SQLException e) {
            System.out.println("Error: " + e.getMessage());
        }
    }
}

// try-with-resources:
// - Cierra automaticamente los recursos al salir del bloque
// - Equivalente a finally con close()
// - Mas seguro y mas limpio
// - Requiere que la clase implemente AutoCloseable (Connection lo hace)

// Clases que implementan AutoCloseable:
// - Connection
// - Statement
// - PreparedStatement
// - ResultSet

