Un `Statement` permite ejecutar sentencias SQL directamente desde Java.

### Crear un Statement
```java
try (Connection conn = DriverManager.getConnection(url, user, pass);
     Statement stmt = conn.createStatement()) {

    // Usar stmt para ejecutar SQL...
}
```

### Tipos de ejecucion

| Metodo | Uso | Devuelve |
|--------|-----|----------|
| `executeQuery(sql)` | SELECT | ResultSet con los resultados |
| `executeUpdate(sql)` | INSERT, UPDATE, DELETE | int con el numero de filas afectadas |
| `execute(sql)` | Cualquier SQL | boolean (true si es ResultSet) |

### Ejemplo: SELECT
```java
Statement stmt = conn.createStatement();
ResultSet rs = stmt.executeQuery("SELECT * FROM alumnos");

while (rs.next()) {
    String nombre = rs.getString("nombre");
    double nota = rs.getDouble("nota_media");
    System.out.println(nombre + ": " + nota);
}
rs.close();
```

### Ejemplo: INSERT
```java
int filas = stmt.executeUpdate(
    "INSERT INTO alumnos (nombre, email, nota_media) VALUES ('Ana', 'ana@email.com', 8.5)"
);
System.out.println("Filas insertadas: " + filas);
```

import java.sql.*;

public class EjemploResultSet {

    public static void main(String[] args) {
        String url = "jdbc:postgresql://localhost:5432/test";

        try (Connection conn = DriverManager.getConnection(url, "postgres", "password");
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery("SELECT * FROM alumnos")) {

            // Iterar sobre los resultados
            while (rs.next()) {
                // Obtener datos por nombre de columna
                long id = rs.getLong("id");
                String nombre = rs.getString("nombre");
                String email = rs.getString("email");
                double nota = rs.getDouble("nota_media");

                // Obtener datos por indice (1 basado)
                // long id2 = rs.getLong(1);
                // String nombre2 = rs.getString(2);

                System.out.printf("ID: %d | Nombre: %s | Email: %s | Nota: %.2f%n",
                    id, nombre, email, nota);
            }

        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}

// Metodos de ResultSet para obtener datos:
// - getString(columna): obtiene un String
// - getDouble(columna): obtiene un double
// - getInt(columna): obtiene un int
// - getLong(columna): obtiene un long
// - getBoolean(columna): obtiene un boolean
// - getDate(columna): obtiene un java.sql.Date
// - getTimestamp(columna): obtiene un java.sql.Timestamp
//
// Puedes usar el nombre de la columna o su indice (1-based)
// rs.next() avanza al siguiente resultado y devuelve false si no hay mas

import java.sql.*;

public class CRUDCompleto {

    private static final String URL = "jdbc:postgresql://localhost:5432/test";

    public static void main(String[] args) {

        try (Connection conn = DriverManager.getConnection(URL, "postgres", "password")) {

            Statement stmt = conn.createStatement();

            // === CREATE: Insertar alumnos ===
            String insert1 = "INSERT INTO alumnos (nombre, email, nota_media) " +
                "VALUES ('Ana Garcia', 'ana@email.com', 8.5)";
            String insert2 = "INSERT INTO alumnos (nombre, email, nota_media) " +
                "VALUES ('Carlos Ruiz', 'carlos@email.com', 7.2)";
            String insert3 = "INSERT INTO alumnos (nombre, email, nota_media) " +
                "VALUES ('Maria Lopez', 'maria@email.com', 9.1)";

            stmt.executeUpdate(insert1);
            stmt.executeUpdate(insert2);
            int filas = stmt.executeUpdate(insert3);
            System.out.println("Alumnos insertados: " + filas);

            // === READ: Consultar alumnos ===
            ResultSet rs = stmt.executeQuery("SELECT * FROM alumnos ORDER BY nota_media DESC");
            System.out.println("\nListado de alumnos:");
            while (rs.next()) {
                System.out.printf("  %d. %s (%s) - Nota: %.2f%n",
                    rs.getLong("id"),
                    rs.getString("nombre"),
                    rs.getString("email"),
                    rs.getDouble("nota_media"));
            }
            rs.close();

            // === UPDATE: Modificar nota de Ana ===
            String update = "UPDATE alumnos SET nota_media = 9.0 WHERE nombre = 'Ana Garcia'";
            int modificadas = stmt.executeUpdate(update);
            System.out.println("\nAlumnos modificados: " + modificadas);

            // Verificar cambio
            rs = stmt.executeQuery("SELECT * WHERE nombre = 'Ana Garcia'");
            if (rs.next()) {
                System.out.printf("  Ana: nueva nota = %.2f%n", rs.getDouble("nota_media"));
            }
            rs.close();

            // === DELETE: Eliminar Carlos ===
            String delete = "DELETE FROM alumnos WHERE nombre = 'Carlos Ruiz'";
            int eliminadas = stmt.executeUpdate(delete);
            System.out.println("\nAlumnos eliminados: " + eliminadas);

            // Listar restantes
            rs = stmt.executeQuery("SELECT COUNT(*) AS total FROM alumnos");
            if (rs.next()) {
                System.out.println("Alumnos restantes: " + rs.getInt("total"));
            }
            rs.close();

            stmt.close();

        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}

// Flujo CRUD:
// 1. INSERT: executeUpdate() -> int (filas insertadas)
// 2. SELECT: executeQuery() -> ResultSet (iterar con next())
// 3. UPDATE: executeUpdate() -> int (filas modificadas)
// 4. DELETE: executeUpdate() -> int (filas eliminadas)

