import java.sql.*;

public class EjemploPreparedStatement {

    private static final String URL = "jdbc:postgresql://localhost:5432/test";

    public static void main(String[] args) {

        try (Connection conn = DriverManager.getConnection(URL, "postgres", "password")) {

            // === INSERT con PreparedStatement ===
            String insertSql = "INSERT INTO alumnos (nombre, email, nota_media) VALUES (?, ?, ?)";

            try (PreparedStatement ps = conn.prepareStatement(insertSql)) {
                ps.setString(1, "Ana Garcia");     // Parametro 1: nombre
                ps.setString(2, "ana@email.com");  // Parametro 2: email
                ps.setDouble(3, 8.5);               // Parametro 3: nota
                int filas = ps.executeUpdate();
                System.out.println("Alumno insertado: " + filas + " fila(s)");
            }

            // === SELECT con PreparedStatement ===
            String selectSql = "SELECT * FROM alumnos WHERE nota_media >= ?";

            try (PreparedStatement ps = conn.prepareStatement(selectSql)) {
                ps.setDouble(1, 7.0); // Nota minima: 7.0

                try (ResultSet rs = ps.executeQuery()) {
                    System.out.println("\nAlumnos con nota >= 7.0:");
                    while (rs.next()) {
                        System.out.printf("  %s (%s) - Nota: %.2f%n",
                            rs.getString("nombre"),
                            rs.getString("email"),
                            rs.getDouble("nota_media"));
                    }
                }
            }

            // === UPDATE con PreparedStatement ===
            String updateSql = "UPDATE alumnos SET nota_media = ? WHERE email = ?";

            try (PreparedStatement ps = conn.prepareStatement(updateSql)) {
                ps.setDouble(1, 9.5);
                ps.setString(2, "ana@email.com");
                int modificadas = ps.executeUpdate();
                System.out.println("\nAlumnos modificados: " + modificadas);
            }

            // === DELETE con PreparedStatement ===
            String deleteSql = "DELETE FROM alumnos WHERE nombre = ?";

            try (PreparedStatement ps = conn.prepareStatement(deleteSql)) {
                ps.setString(1, "Ana Garcia");
                int eliminadas = ps.executeUpdate();
                System.out.println("Alumnos eliminados: " + eliminadas);
            }

        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}

// Claves de PreparedStatement:
// 1. conn.prepareStatement(sql) crea la sentencia
// 2. ps.setXxx(indice, valor) establece los parametros (1-based)
// 3. ps.executeUpdate() para INSERT/UPDATE/DELETE
// 4. ps.executeQuery() para SELECT
// 5. try-with-resources cierra PreparedStatement y ResultSet automaticamente

import java.sql.*;

public class ObtenerIDGenerado {

    public static void main(String[] args) {
        String url = "jdbc:postgresql://localhost:5432/test";

        try (Connection conn = DriverManager.getConnection(url, "postgres", "password")) {

            // Usar RETURNING para obtener el ID en PostgreSQL
            String sql = "INSERT INTO alumnos (nombre, email, nota_media) VALUES (?, ?, ?) RETURNING id";

            try (PreparedStatement ps = conn.prepareStatement(sql)) {
                ps.setString(1, "Nuevo Alumno");
                ps.setString(2, "nuevo@email.com");
                ps.setDouble(3, 7.0);

                try (ResultSet rs = ps.executeQuery()) {
                    if (rs.next()) {
                        long idGenerado = rs.getLong(1);
                        System.out.println("ID generado: " + idGenerado);
                    }
                }
            }

            // Alternativa sin RETURNING (menos eficiente pero portable)
            String sql2 = "INSERT INTO alumnos (nombre, email, nota_media) VALUES (?, ?, ?)";
            try (PreparedStatement ps = conn.prepareStatement(sql2,
                    Statement.RETURN_GENERATED_KEYS)) {
                ps.setString(1, "Otro Alumno");
                ps.setString(2, "otro@email.com");
                ps.setDouble(3, 8.0);
                ps.executeUpdate();

                try (ResultSet keys = ps.getGeneratedKeys()) {
                    if (keys.next()) {
                        System.out.println("ID generado: " + keys.getLong(1));
                    }
                }
            }

        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}

// Obtener el ID generado:
// 1. PostgreSQL: usar RETURNING id (recomendado)
// 2. Portabilidad: Statement.RETURN_GENERATED_KEYS + getGeneratedKeys()

