public static List<String> buscarAlumno(Connection conn, String nombre) throws SQLException {
    String sql = "SELECT nombre, email FROM alumnos WHERE nombre LIKE ?";
    List<String> resultados = new ArrayList<>();

    try (PreparedStatement ps = conn.prepareStatement(sql)) {
        ps.setString(1, "%" + nombre + "%");
        try (ResultSet rs = ps.executeQuery()) {
            while (rs.next()) {
                resultados.add(rs.getString("nombre") + " - " + rs.getString("email"));
