import java.sql.*;
import java.util.ArrayList;
import java.util.List;

/**
 * DAO (Data Access Object) para la entidad Alumno.
 * Encapsula toda la logica de acceso a PostgreSQL.
 */
public class AlumnoDAO {

    private final Connection conn;

    public AlumnoDAO(Connection conn) {
        this.conn = conn;
    }

    /** Crea la tabla si no existe. */
    public void crearTabla() throws SQLException {
        String sql = "CREATE TABLE IF NOT EXISTS alumnos (" +
            "id SERIAL PRIMARY KEY, " +
            "nombre VARCHAR(100) NOT NULL, " +
            "email VARCHAR(100) UNIQUE NOT NULL, " +
            "nota_media DECIMAL(4,2) DEFAULT 0.00)";
        try (Statement stmt = conn.createStatement()) {
            stmt.execute(sql);
        }
    }

    /** Agrega un alumno. Devuelve el ID generado. */
    public long agregar(String nombre, String email, double nota) throws SQLException {
        String sql = "INSERT INTO alumnos (nombre, email, nota_media) VALUES (?, ?, ?) RETURNING id";
        try (PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, nombre);
            ps.setString(2, email);
            ps.setDouble(3, nota);
            try (ResultSet rs = ps.executeQuery()) {
                rs.next();
                return rs.getLong(1);
            }
        }
    }

    /** Lista todos los alumnos. */
    public List<String[]> listar() throws SQLException {
        List<String[]> alumnos = new ArrayList<>();
        String sql = "SELECT id, nombre, email, nota_media FROM alumnos ORDER BY nombre";
        try (PreparedStatement ps = conn.prepareStatement(sql);
             ResultSet rs = ps.executeQuery()) {
            while (rs.next()) {
                alumnos.add(new String[]{
                    String.valueOf(rs.getLong("id")),
                    rs.getString("nombre"),
                    rs.getString("email"),
                    String.format("%.2f", rs.getDouble("nota_media"))
                });
            }
        }
        return alumnos;
    }

    /** Busca un alumno por ID. */
    public String[] buscarPorId(long id) throws SQLException {
        String sql = "SELECT * FROM alumnos WHERE id = ?";
        try (PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setLong(1, id);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    return new String[]{
                        String.valueOf(rs.getLong("id")),
                        rs.getString("nombre"),
                        rs.getString("email"),
                        String.format("%.2f", rs.getDouble("nota_media"))
                    };
                }
            }
        }
        return null;
    }

    /** Actualiza un alumno existente. */
    public boolean actualizar(long id, String nombre, String email, double nota) throws SQLException {
        String sql = "UPDATE alumnos SET nombre = ?, email = ?, nota_media = ? WHERE id = ?";
        try (PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, nombre);
            ps.setString(2, email);
            ps.setDouble(3, nota);
            ps.setLong(4, id);
            return ps.executeUpdate() > 0;
        }
    }

    /** Elimina un alumno por ID. */
    public boolean eliminar(long id) throws SQLException {
        String sql = "DELETE FROM alumnos WHERE id = ?";
        try (PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setLong(1, id);
            return ps.executeUpdate() > 0;
        }
    }

    /** Busca alumnos por nombre parcial (LIKE). */
    public List<String[]> buscarPorNombre(String nombre) throws SQLException {
        List<String[]> resultados = new ArrayList<>();
        String sql = "SELECT * FROM alumnos WHERE nombre ILIKE ? ORDER BY nombre";
        try (PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, "%" + nombre + "%");
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    resultados.add(new String[]{
                        String.valueOf(rs.getLong("id")),
                        rs.getString("nombre"),
                        rs.getString("email"),
                        String.format("%.2f", rs.getDouble("nota_media"))
                    });
                }
            }
        }
        return resultados;
    }

    /** Cuenta el numero total de alumnos. */
    public int contar() throws SQLException {
        try (Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery("SELECT COUNT(*) FROM alumnos")) {
            rs.next();
            return rs.getInt(1);
        }
    }
}

import java.sql.*;
import java.util.List;
import java.util.Scanner;

public class AppPrincipal {

    private static final String URL = "jdbc:postgresql://localhost:5432/test";
    private static final Scanner sc = new Scanner(System.in);

    public static void main(String[] args) {
        try (Connection conn = DriverManager.getConnection(URL, "postgres", "password")) {
            AlumnoDAO dao = new AlumnoDAO(conn);
            dao.crearTabla();

            boolean salir = false;
            while (!salir) {
                mostrarMenu();
                int opcion = leerEntero("Opcion: ");

                try {
                    switch (opcion) {
                        case 1 -> listarAlumnos(dao);
                        case 2 -> agregarAlumno(dao);
                        case 3 -> buscarAlumno(dao);
                        case 4 -> modificarAlumno(dao);
                        case 5 -> eliminarAlumno(dao);
                        case 6 -> estadisticas(dao);
                        case 0 -> salir = true;
                        default -> System.out.println("Opcion no valida.");
                    }
                } catch (SQLException e) {
                    System.out.println("Error BD: " + e.getMessage());
                }
                System.out.println();
            }
            System.out.println("Hasta pronto!");

        } catch (SQLException e) {
            System.out.println("Error de conexion: " + e.getMessage());
        }
    }

    private static void mostrarMenu() {
        System.out.println("=== GESTOR DE ALUMNOS ===");
        System.out.println("1. Listar alumnos");
        System.out.println("2. Agregar alumno");
        System.out.println("3. Buscar alumno");
        System.out.println("4. Modificar alumno");
        System.out.println("5. Eliminar alumno");
        System.out.println("6. Estadisticas");
        System.out.println("0. Salir");
    }

    private static void agregarAlumno(AlumnoDAO dao) throws SQLException {
        System.out.print("Nombre: ");
        String nombre = sc.nextLine().trim();
        System.out.print("Email: ");
        String email = sc.nextLine().trim();
        System.out.print("Nota media: ");
        double nota = Double.parseDouble(sc.nextLine().trim());

        long id = dao.agregar(nombre, email, nota);
        System.out.println("Alumno agregado con ID: " + id);
    }

    private static void listarAlumnos(AlumnoDAO dao) throws SQLException {
        List<String[]> alumnos = dao.listar();
        if (alumnos.isEmpty()) {
            System.out.println("No hay alumnos.");
            return;
        }
        System.out.printf("%-5s %-20s %-25s %8s%n", "ID", "Nombre", "Email", "Nota");
        System.out.println("-".repeat(58));
        for (String[] a : alumnos) {
            System.out.printf("%-5s %-20s %-25s %8s%n", a[0], a[1], a[2], a[3]);
        }
    }

    private static void buscarAlumno(AlumnoDAO dao) throws SQLException {
        System.out.print("Nombre a buscar: ");
        String nombre = sc.nextLine().trim();
        List<String[]> encontrados = dao.buscarPorNombre(nombre);
        if (encontrados.isEmpty()) {
            System.out.println("No se encontraron alumnos.");
        } else {
            encontrados.forEach(a ->
                System.out.printf("  %s. %s (%s) - Nota: %s%n", a[0], a[1], a[2], a[3]));
        }
    }

    private static void modificarAlumno(AlumnoDAO dao) throws SQLException {
        System.out.print("ID del alumno a modificar: ");
        long id = Long.parseLong(sc.nextLine().trim());
        String[] actual = dao.buscarPorId(id);
        if (actual == null) {
            System.out.println("Alumno no encontrado.");
            return;
        }
        System.out.printf("Actual: %s | %s | %s%n", actual[1], actual[2], actual[3]);

        System.out.print("Nuevo nombre (Enter para mantener): ");
        String nombre = sc.nextLine().trim();
        if (nombre.isEmpty()) nombre = actual[1];

        System.out.print("Nuevo email (Enter para mantener): ");
        String email = sc.nextLine().trim();
        if (email.isEmpty()) email = actual[2];

        System.out.print("Nueva nota (Enter para mantener): ");
        String notaStr = sc.nextLine().trim();
        double nota = notaStr.isEmpty() ? Double.parseDouble(actual[3]) : Double.parseDouble(notaStr);

        if (dao.actualizar(id, nombre, email, nota)) {
            System.out.println("Alumno actualizado.");
        } else {
            System.out.println("No se pudo actualizar.");
        }
    }

    private static void eliminarAlumno(AlumnoDAO dao) throws SQLException {
        System.out.print("ID del alumno a eliminar: ");
        long id = Long.parseLong(sc.nextLine().trim());
        if (dao.eliminar(id)) {
            System.out.println("Alumno eliminado.");
        } else {
            System.out.println("Alumno no encontrado.");
        }
    }

    private static void estadisticas(AlumnoDAO dao) throws SQLException {
        System.out.println("Total de alumnos: " + dao.contar());
    }

    private static int leerEntero(String mensaje) {
        System.out.print(mensaje);
        try {
            return Integer.parseInt(sc.nextLine().trim());
        } catch (NumberFormatException e) {
            return -1;
        }
    }
}

